import itertools

def get_pillars(n):
    z_pillars = list(itertools.product(range(n), repeat=2))
    x_pillars = list(itertools.product(range(n), repeat=2))
    y_pillars = list(itertools.product(range(n), repeat=2))
    return z_pillars, x_pillars, y_pillars

def share(p1, p2, n):
    type1, c1 = p1
    type2, c2 = p2
    if type1 == type2:
        return max(abs(c1[0]-c2[0]), abs(c1[1]-c2[1])) <= 1
    if type1 == 0 and type2 == 1: return abs(c1[1] - c2[0]) <= 1
    if type1 == 1 and type2 == 0: return share((0, c2), (1, c1), n)
    if type1 == 0 and type2 == 2: return abs(c1[0] - c2[0]) <= 1
    if type1 == 2 and type2 == 0: return share((0, c2), (2, c1), n)
    if type1 == 1 and type2 == 2: return abs(c1[1] - c2[1]) <= 1
    if type1 == 2 and type2 == 1: return share((1, c2), (2, c1), n)
    return False

