def test_n(n):
    z_p, x_p, y_p = [list(itertools.product(range(n), repeat=2))] * 3
    all_p = [(0, p) for p in z_p] + [(1, p) for p in x_p] + [(2, p) for p in y_p]
    queries = [(x, y, (x + y) % n) for x in range(n) for y in range(n)]

